const D = { energy: .6, scale: 1, density: .5, neglect: .5, speed: 1, hue: 176, x: .5, y: .9, alpha: 1, style: 'glasshouse', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const poly=(sty==='polytunnel'), bare=(sty==='frame'), pris=(sty==='prism'), soot=(sty==='sooted');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), ng=cl(P.neglect,0,1.4), act=P.act;
const hx=cl(P.x,.05,.95)*W, by=cl(P.y,.35,1.12)*Hh;

const GW=u*.62*sc, WH=u*.28*sc, RR=u*.15*sc;
const DX=GW*.42, DY=-WH*.30;                 // the flank recedes up-right
const x0=hx-GW*.5, yW=by-WH, yR=yW-RR;
const NC=Math.max(2,Math.round(3+dens*3));   // glazing bays across
const NRw=Math.max(2,Math.round(2+dens*2));  // glazing rows up the wall

S.bass=(S.bass||0)*.85+(A.bass||0)*.15;
const T=K.t*spd;
const glow=(.30+.80*en)*(.55+.5*K.intensity)+S.bass*.28;

// ---- the sun behind the glass: bounded wobbles at incommensurate rates ----
// (amplitudes/rates checked numerically so no 8s window can catch it re-phased)
let sunU=.62*Math.sin(T*.113)+.28*Math.sin(T*.197+1.7)+.14*Math.sin(T*.311);
let sunV=.50+.26*Math.sin(T*.083+.9)+.10*Math.sin(T*.163);
if(act==='dusk'){ sunU*=.8; sunV=.24+.14*Math.sin(T*.061)+.06*Math.sin(T*.131); }
else if(act==='squall') sunU*=1.15;
const sunX=hx+sunU*GW*.95, sunY=yR+ (1-sunV)*(by-yR)*.7 - RR*.3;

// wind: only the plants and the loose sheeting feel it
let gust=.3+.6*en; if(act==='squall') gust*=1.7; else if(act==='dusk') gust*=.6;
const wind=(q,ph)=>(.55*Math.sin(T*.77+q+ph)+.28*Math.sin(T*1.33+q*1.7+ph*.6)+.17*Math.sin(T*2.09+q*.5));

// ---- the shell, in gable-end + flank ---------------------------------------
const ridgeY=yR, apexX=hx;
const gableTop=fx=>{                            // the roof line of the gable end
  const t=Math.abs(fx-apexX)/(GW*.5);
  return yR+cl(t,0,1)*(yW-yR);
};

function panes(){
  const ps=[];
  // gable-end wall glazing
  for(let i=0;i<NC;i++) for(let j=0;j<NRw;j++){
    const a=x0+(i/NC)*GW, b=x0+((i+1)/NC)*GW;
    const t0=yW+(j/NRw)*(by-yW), t1=yW+((j+1)/NRw)*(by-yW);
    ps.push({q:[[a,t0],[b,t0],[b,t1],[a,t1]], id:i*7+j, face:0});
  }
  // gable-end roof glazing
  for(let i=0;i<NC;i++){
    const a=x0+(i/NC)*GW, b=x0+((i+1)/NC)*GW;
    ps.push({q:[[a,gableTop(a)],[b,gableTop(b)],[b,yW],[a,yW]], id:i*13+91, face:1});
  }
  // the flank, receding: wall + roof
  for(let i=0;i<NC;i++) for(let j=0;j<NRw;j++){
    const f0=i/NC, f1=(i+1)/NC;
    const ax=x0+GW+DX*f0, bx2=x0+GW+DX*f1;
    const ay=yW+DY*f0, by2=yW+DY*f1;
    const t0=ay+(j/NRw)*(by+DY*f0-ay), t1=ay+((j+1)/NRw)*(by+DY*f0-ay);
    const t2=by2+(j/NRw)*(by+DY*f1-by2), t3=by2+((j+1)/NRw)*(by+DY*f1-by2);
    ps.push({q:[[ax,t0],[bx2,t2],[bx2,t3],[ax,t1]], id:i*17+j+31, face:2});
  }
  for(let i=0;i<NC;i++){
    const f0=i/NC, f1=(i+1)/NC;
    const ax=x0+GW+DX*f0, bx2=x0+GW+DX*f1;
    ps.push({q:[[apexX+GW*.5*0+ax-GW*0,yR+DY*f0],[bx2,yR+DY*f1],[bx2,yW+DY*f1],[ax,yW+DY*f0]], id:i*19+61, face:3});
  }
  for(const p of ps){
    p.gone=fr(p.id*1.3)<(bare?.72:(ng*.13));      // broken out / never glazed
    p.algae=fr(p.id*1.3+1);
    p.cx=(p.q[0][0]+p.q[1][0]+p.q[2][0]+p.q[3][0])*.25;
    p.cy=(p.q[0][1]+p.q[1][1]+p.q[2][1]+p.q[3][1])*.25;
  }
  return ps;
}

const pkey=[sd,NC,NRw,Math.round(sc*40),sty,Math.round(ng*6),Math.round(P.x*120),Math.round(P.y*120),W,Hh].join('|');
if(!S.panes||S.pk!==pkey){ S.panes=panes(); S.pk=pkey; }
const ps=S.panes;

const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// the whole footprint, used to keep everything we do INSIDE the glasshouse
const shell=()=>{
  dc.beginPath();
  dc.moveTo(x0,by); dc.lineTo(x0,yW); dc.lineTo(apexX,yR);
  dc.lineTo(x0+GW,yW); dc.lineTo(x0+GW+DX,yW+DY);
  dc.lineTo(apexX+DX,yR+DY); dc.lineTo(x0+GW+DX,yW+DY);
  dc.lineTo(x0+GW+DX,by+DY); dc.lineTo(x0+GW,by); dc.closePath();
};

// ---- what is growing in there: silhouettes pressed against the glass ------
if(!bare){
  dc.save(); shell(); dc.clip();
  noStroke();
  const NV=Math.round((6+dens*10)*(.4+ng*.5));
  for(let i=0;i<NV;i++){
    const px=x0+fr(i*3.7)*(GW+DX*.9), pbase=by+DY*fr(i*3.7)*.6;
    const ht=(WH+RR)*(.35+fr(i*3.7+1)*.75);
    const vh=md(H+fr(i*3.7+2)*40-20,360);
    for(let j=0;j<7;j++){
      const f=j/7;
      const sway=wind(f*2.0,i*2.3)*GW*.012*gust*f*f;
      const lx=px+sway+(fr(i*3.7+3)-.5)*ht*.3*f;
      const ly=pbase-ht*f;
      const lsz=GW*.035*(.4+fr(i*3.7+j+4)*.9)*(1-f*.3);
      fill(vh,cl(30+fr(i*3.7+j+5)*26,0,64),cl(12+22*glow*(1-f*.4),3,52),cl(34+16*glow,0,60)*AL);
      push(); translate(lx,ly); rotate((fr(i*3.7+j+6)-.5)*2+wind(f,i*2.3)*.4);
      ellipse(0,0,lsz*2.1,lsz*.9); pop();
    }
  }
  dc.restore();
}

// ---- the glass itself: translucent, ALWAYS. a glasshouse that reads as an
// opaque panel has stopped being a glasshouse and started clobbering the bg.
for(const p of ps){
  if(p.gone) continue;
  const d=Math.hypot(p.cx-sunX,p.cy-sunY)/(GW*.85);
  const lit=Math.exp(-d*d*1.1);
  let h2,s2,b2,a2;
  if(pris){                                   // thin-film interference across the glazing
    h2=md(H+p.algae*300+lit*90+T*3,360); s2=54; b2=28+62*lit; a2=(24+34*lit)*AL;
  } else if(poly){
    h2=md(H+8,360); s2=10+8*p.algae; b2=26+50*lit; a2=(26+30*lit)*AL;
  } else if(soot){
    h2=md(H+10,360); s2=6; b2=8+30*lit*(1-p.algae*.6); a2=(30+26*lit)*AL;
  } else {
    h2=md(H-6+p.algae*24,360); s2=14+22*p.algae; b2=22+58*lit; a2=(20+30*lit)*AL;
  }
  fill(h2,cl(s2,0,70),cl(b2,3,94),cl(a2,0,72));
  beginShape(); for(const v of p.q) vertex(v[0],v[1]); endShape(CLOSE);
  // the sheen on a pane turned toward the sun
  if(lit>.14){
    fill(pris?md(H+p.algae*300+140,360):md(H+4,360),pris?40:8,cl(70+28*glow,0,100),cl(30*lit*glow,0,44)*AL);
    beginShape();
    vertex(p.q[0][0],p.q[0][1]);
    vertex(p.q[0][0]+(p.q[1][0]-p.q[0][0])*.55,p.q[0][1]+(p.q[1][1]-p.q[0][1])*.55);
    vertex(p.q[3][0]+(p.q[2][0]-p.q[3][0])*.30,p.q[3][1]+(p.q[2][1]-p.q[3][1])*.30);
    vertex(p.q[3][0],p.q[3][1]);
    endShape(CLOSE);
  }
}

// ---- cached: the dirt, algae and limescale ON the glass, plus the bars ----
const bkey=[W,Hh,sty,sd,Math.round(H),Math.round(sc*40),NC,NRw,Math.round(ng*6),Math.round(P.x*120),Math.round(P.y*120)].join('|');
if(!S.base||S.bk!==bkey||S.base.width!==W||S.base.height!==Hh){
  const g=(S.base&&S.base.width===W&&S.base.height===Hh)?S.base:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const barH=poly?md(H+186,360):(soot?md(H+10,360):md(H+178,360));
  const gd=g.drawingContext;

  // grime, algae blooms and rain-tracks, clipped to the glazing
  gd.save();
  gd.beginPath();
  gd.moveTo(x0,by); gd.lineTo(x0,yW); gd.lineTo(apexX,yR);
  gd.lineTo(x0+GW,yW); gd.lineTo(x0+GW+DX,yW+DY);
  gd.lineTo(x0+GW+DX,by+DY); gd.lineTo(x0+GW,by); gd.closePath();
  gd.clip();
  for(let k=0;k<Math.round(90+ng*150);k++){       // algae creeping from every corner
    const ax=x0+fr(k*2.1)*(GW+DX), ay=yR+fr(k*2.1+1)*(by-yR);
    const rr=GW*(.01+fr(k*2.1+2)*.05)*(.5+ng);
    g.fill(md(H+(soot?4:-16)+fr(k*2.1+3)*30,360), soot?8:34, soot?9:(16+fr(k*2.1+4)*22), 16);
    g.ellipse(ax,ay,rr*2.2,rr*1.6);
  }
  for(let k=0;k<Math.round(40+ng*40);k++){        // rain has cleaned tracks down the dirt
    const ax=x0+fr(k*3.3+9)*(GW+DX);
    g.fill(md(H+2,360),4,soot?52:64,soot?16:9);
    g.rect(ax,yW+fr(k*3.3+10)*(by-yW)*.3,GW*.004*(1+fr(k*3.3+11)*2),(by-yW)*(.3+fr(k*3.3+12)*.7));
  }
  gd.restore();

  // ---- the glazing bars: the actual structure ---------------------------
  const bw=Math.max(1.2,GW*.010);
  const bar=(ax,ay,bx2,by2,w)=>{
    const dx=bx2-ax, dy=by2-ay, len=Math.hypot(dx,dy); if(len<1) return;
    g.push(); g.translate(ax,ay); g.rotate(Math.atan2(dy,dx));
    g.fill(barH,poly?10:(soot?5:8),soot?12:(poly?30:26),94); g.rect(0,-w*.5,len,w);
    g.fill(barH,poly?8:6,soot?24:(poly?54:58),74); g.rect(0,-w*.42,len,w*.30);
    g.pop();
  };
  for(let i=0;i<=NC;i++){                       // gable uprights
    const ax=x0+(i/NC)*GW; bar(ax,by,ax,gableTop(ax),bw);
  }
  for(let j=0;j<=NRw;j++){ const ty=yW+(j/NRw)*(by-yW); bar(x0,ty,x0+GW,ty,bw*.8); }
  bar(x0,yW,apexX,yR,bw*1.15); bar(x0+GW,yW,apexX,yR,bw*1.15);     // the rafters
  bar(x0,yW,x0+GW,yW,bw*1.1);                                       // the eaves
  bar(apexX,yR,apexX+DX,yR+DY,bw*1.2);                              // the ridge
  for(let i=0;i<=NC;i++){                       // flank uprights + rafters
    const f=i/NC, ax=x0+GW+DX*f, ay=yW+DY*f;
    bar(ax,by+DY*f,ax,ay,bw*.9); bar(ax,ay,apexX+DX*f,yR+DY*f,bw*.8);
  }
  bar(x0+GW,yW,x0+GW+DX,yW+DY,bw*1.1);
  bar(x0+GW,by,x0+GW+DX,by+DY,bw*1.1);
  // ---- dwarf wall: the glasshouse stands on brick ----------------------
  const dwH=(by-yW)*.22;
  for(let i=0;i<Math.round(14+dens*10);i++){
    const bx2=x0+(i/Math.round(14+dens*10))*GW;
    g.fill(md(H+(soot?6:172),360),soot?6:26,(soot?10:16)+fr(i*4.1)*10,96);
    g.rect(bx2,by-dwH,GW/Math.round(14+dens*10)+1,dwH);
    g.fill(md(H+(soot?6:172),360),soot?5:22,(soot?16:24)+fr(i*4.1+1)*10,60);
    g.rect(bx2,by-dwH,GW/Math.round(14+dens*10)+1,dwH*.18);
  }
  // ---- the door, and a roof vent propped open --------------------------
  const dw=GW*.20, dh=(by-yW)*.78;
  bar(hx-dw*.5,by,hx-dw*.5,by-dh,bw*1.1); bar(hx+dw*.5,by,hx+dw*.5,by-dh,bw*1.1);
  bar(hx-dw*.5,by-dh,hx+dw*.5,by-dh,bw*1.1);
  g.fill(barH,8,46,80); g.circle(hx+dw*.32,by-dh*.5,Math.max(1.5,GW*.008));
  S.base=g; S.bk=bkey;
}
image(S.base,0,0);

// ---- the sun's own bloom, kept INSIDE the glass ---------------------------
{
  dc.save(); shell(); dc.clip();
  dc.globalCompositeOperation='lighter';
  const rr=GW*(.42+.16*Math.sin(T*.071+1.2))*(.5+.8*en);
  const hg=dc.createRadialGradient(sunX,sunY,0,sunX,sunY,Math.max(4,rr));
  const ha=(0.10+0.20*glow)*AL;
  const warm=pris?'200,230,255':(act==='dusk'?'255,178,120':'255,238,198');
  hg.addColorStop(0,'rgba('+warm+','+ha.toFixed(3)+')');
  hg.addColorStop(.5,'rgba('+warm+','+(ha*.34).toFixed(3)+')');
  hg.addColorStop(1,'rgba('+warm+',0)');
  dc.fillStyle=hg; dc.fillRect(sunX-rr,sunY-rr,rr*2,rr*2);
  dc.globalCompositeOperation=oldOp;
  dc.restore();
}

// ---- condensation: droplets tracking down the inside of the glass --------
if(!bare&&act!=='dusk'){
  dc.save(); shell(); dc.clip();
  noStroke();
  const ND=Math.round((10+dens*18)*(.4+ng*.6));
  for(let k=0;k<ND;k++){
    const dx2=x0+fr(k*5.7)*(GW+DX);
    const ph=md(T*.043*(.5+fr(k*5.7+1))+fr(k*5.7+2),1);
    const y0=yW+DY*.3, y1=by;
    const dy2=y0+ph*ph*(y1-y0);
    const rr=GW*.006*(.6+fr(k*5.7+3)*1.1);
    fill(md(H+4,360),6,cl(64+30*glow,0,100),cl(46*(1-ph*.4),0,66)*AL);
    ellipse(dx2,dy2,rr*1.5,rr*2.4);
    fill(md(H+4,360),4,cl(50+26*glow,0,96),cl(16*(1-ph),0,24)*AL);   // the track it leaves
    rect(dx2-rr*.28,y0,rr*.56,dy2-y0);
  }
  dc.restore();
}

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0;
noStroke(); noTint();
